import { listProjectMemories } from "./mcp-client.js";
const LEGACY_PREFERENCE_PREFIX = "USER — Preference:";
function normalizeText(text) {
    return text.trim().replace(/\s+/g, " ");
}
function normalizeLegacyPreferenceContent(text) {
    return normalizeText(text).toLowerCase();
}
function parseLegacyPreferenceContent(content) {
    const trimmed = content.trim();
    if (!trimmed.startsWith(LEGACY_PREFERENCE_PREFIX))
        return null;
    const raw = trimmed.slice(LEGACY_PREFERENCE_PREFIX.length).trim();
    return raw || null;
}
function normalizeLegacyPreferenceStatus(value) {
    if (value === "confirmed" || value === "candidate")
        return value;
    return null;
}
function extractLegacyPreferenceStatus(memory) {
    const metadata = memory.metadata;
    if (metadata && typeof metadata === "object" && !Array.isArray(metadata)) {
        const status = normalizeLegacyPreferenceStatus(metadata.status);
        if (status)
            return status;
    }
    return "confirmed";
}
function mergeLegacyPreference(existing, incoming) {
    if (!existing)
        return incoming;
    if (existing.status === "confirmed")
        return existing;
    if (incoming.status === "confirmed")
        return incoming;
    return existing;
}
function collectLegacyPreferences(memories) {
    const deduped = new Map();
    for (const memory of memories) {
        const parsed = parseLegacyPreferenceContent(memory.content);
        if (!parsed)
            continue;
        const normalized = normalizeLegacyPreferenceContent(parsed);
        if (!normalized)
            continue;
        const incoming = {
            id: String(memory.id ?? parsed),
            content: parsed,
            status: extractLegacyPreferenceStatus(memory),
            metadata: memory.metadata && typeof memory.metadata === "object" && !Array.isArray(memory.metadata)
                ? (memory.metadata)
                : undefined,
        };
        deduped.set(normalized, mergeLegacyPreference(deduped.get(normalized), incoming));
    }
    return [...deduped.values()];
}
function formatLegacyPreferenceSection(title, hint, values) {
    if (values.length === 0)
        return null;
    return [`## ${title}`, hint, ...values.map((value) => `- ${value}`)].join("\n");
}
export async function listLegacyPreferences(config, context) {
    try {
        const result = await listProjectMemories(config, Math.max(1, config.preferenceLearning.maxStoredPreferences), false, context);
        if (result.status !== "ok") {
            return { ...result, memories: [] };
        }
        const memories = collectLegacyPreferences(result.memories);
        const filtered = memories.map(({ id, content, status, metadata }) => ({
            id,
            content,
            ...(metadata ? { metadata: { ...metadata, status } } : { metadata: { status } }),
        }));
        if (filtered.length === 0) {
            return { ...result, status: "empty", memories: [] };
        }
        return { ...result, memories: filtered };
    }
    catch {
        return {
            status: "failed",
            source: "list",
            memories: [],
            reason: "legacy preference lookup failed",
        };
    }
}
export function formatLegacyPreferencesForInjection(memories) {
    const confirmed = [];
    const candidates = [];
    for (const memory of memories) {
        const parsed = parseLegacyPreferenceContent(memory.content);
        if (!parsed)
            continue;
        const status = extractLegacyPreferenceStatus(memory);
        if (status === "candidate") {
            candidates.push(parsed);
        }
        else {
            confirmed.push(parsed);
        }
    }
    if (confirmed.length === 0 && candidates.length === 0)
        return null;
    const sections = [
        "[MEMORY] Legacy User Preferences",
        formatLegacyPreferenceSection("Confirmed Preferences", "Treat these as strong guidance from prior user signals:", confirmed),
        formatLegacyPreferenceSection("Candidate Preferences", "Tentative hints only — validate before treating as hard rules:", candidates),
    ].filter(Boolean);
    return sections.join("\n\n");
}
